const SPOTS = [{"id": 1, "file": "spot1.html", "name": "林復振商行", "short": "南北貨與大稻埕的商業記憶", "symbol": "🧺", "year": "1853 年起", "address": "臺北市大同區迪化街一段 105 號", "theme": "商業・貿易・家族傳承", "intro": "走進林復振商行，從一間販售南北貨的老商號，看見大稻埕如何從河港貿易聚落逐漸發展成繁華街市。", "story": "林復振商行的歷史與林右藻家族及大稻埕早期商業發展緊密相連。商行自 1853 年起在迪化街經營南北貨，南北貨包含乾貨、海味、食材與年節採買用品，反映過去家庭備料、送禮與節慶生活的需求。商行後來也隨著市場改變，於 1984 年引進日本紅帽子禮盒代理，讓傳統商號在原有商品之外發展新的經營方向。", "memory": "以前準備年菜、辦喜事或逢年過節，許多家庭會到南北貨行採買。乾貨與海味不只是商品，也連結著家族團聚、送禮往來和節慶餐桌。", "question": "如果一家老店能保存一座城市的商業記憶，你會想問店家：這條街以前最熱鬧的時候是什麼樣子？", "map": "林復振商行 臺北市大同區迪化街一段105號", "sources": [["林復振商行官方網站－商行源起", "https://www.linfuzhen.com/about"], ["中央研究院臺灣史研究所－林復振商行", "https://archives.ith.sinica.edu.tw/collections_con.php?no=134"]]}, {"id": 2, "file": "spot2.html", "name": "李亭香", "short": "漢餅、祝福與世代傳承", "symbol": "🥮", "year": "1895 年創立", "address": "臺北市大同區迪化街一段 309 號", "theme": "糕餅・節慶・祝福", "intro": "一塊漢餅不只是點心，也可能是婚禮、祝壽、節慶與家人之間傳遞心意的方式。", "story": "李亭香創立於 1895 年。第一代李騰飛學習製餅手藝後創立餅店，店名「李亭香」與李家騎樓飄出的餅香有關。1951 年，第二代將店鋪拓展到大稻埕迪化街，讓這間餅店與當時熱鬧的商業街區連結在一起。店家持續以傳統漢餅為基礎，也因應不同世代的口味與送禮需求調整產品。", "memory": "漢餅常出現在婚嫁、祝壽與節慶場合。送餅不只是分享食物，也是一種把祝福交到對方手中的儀式。不同造型與名稱，往往承載著平安、團圓或喜慶的寓意。", "question": "你家有沒有一種只有過年、結婚或特別節日才會出現的糕餅？它代表什麼回憶？", "map": "李亭香 臺北市大同區迪化街一段309號", "sources": [["李亭香官方網站－門市資訊", "https://lee-cake.com/locations"], ["臺北旅遊網－迪化街老店採買／感受店家真心情意", "https://travel.taipei/zh-tw/pictorial/article/7646"], ["華山 1914－李亭香品牌故事", "https://www.huashan1914.com/w/huashan1914/exhibition_18072619264740720"]]}, {"id": 3, "file": "spot3.html", "name": "老綿成燈籠店", "short": "從金紙到燈籠的百年工藝", "symbol": "🏮", "year": "1915 年創立", "address": "臺北市大同區迪化街一段 298 號", "theme": "工藝・信仰・節慶", "intro": "紅磚街屋下掛著各式燈籠，這間老店的轉型故事，也映照出台灣民俗與傳統工藝的變化。", "story": "老綿成燈籠店於 1915 年在迪化街開業。依臺北旅遊網的店家訪談，創業初期以金紙批發為主，後來轉向燈籠生意。第三代經營者張美美從小就在店裡幫忙，也見證街區從橋頭市場的熱鬧市集，逐漸轉變為今日融合老店與觀光的新樣貌。燈籠常出現在廟宇、節慶與祈福活動中，象徵光明、平安與祝願。", "memory": "燈籠不只是裝飾。廟會、節慶與祈福時，人們點燈、掛燈，將對家人與生活的祝願寄託其中。手工燈籠也讓傳統工藝在大量製造的時代仍保有獨特價值。", "question": "如果要為自己或家人做一盞燈籠，你會在上面寫下什麼祝福？", "map": "老綿成燈籠店 臺北市大同區迪化街一段298號", "sources": [["臺北旅遊網－老綿成燈籠店故事", "https://www.travel.taipei/file/14115/"], ["老綿成燈籠店－關於我們", "https://laomiancheng.blogspot.com/p/about.html"]]}, {"id": 4, "file": "spot4.html", "name": "食連動魚丸（原味香魚丸）", "short": "一顆魚丸裡的三代手藝", "symbol": "🐟", "year": "1961 年起家", "address": "臺北市大同區迪化街一段 337 號", "theme": "飲食・手藝・家族記憶", "intro": "從家庭工廠到手工魚漿製品品牌，這間店讓人看見日常食物背後的技術、勞動與家族傳承。", "story": "食連動魚丸的前身為味香魚丸，於 1961 年在大稻埕迪化街起家，早期以家庭工廠方式製作魚漿製品，後來逐步發展為食品工廠。店家官方介紹指出，目前由第三代接手，延續魚丸、甜不辣等魚漿製品的製作。2025 年品牌轉型為「食連動魚丸」，並加入面向消費者的展示與體驗，希望讓更多人認識魚漿製品的製作與地方飲食文化。", "memory": "魚丸常出現在湯品、火鍋與家庭餐桌上。對許多人而言，一顆魚丸連結的是市場採買、家人煮飯，以及熟悉的家常味道。", "question": "你記憶中最熟悉的一道家常菜是什麼？它通常是誰煮的？", "map": "食連動魚丸 臺北市大同區迪化街一段337號", "sources": [["臺北市商業處－食連動魚丸改造與品牌故事", "https://www.tcooc.gov.taipei/cp.aspx?n=8D0974959002A45D"], ["食連動魚丸官方網站－關於我們", "https://fishball1961.com/about.php"], ["食連動魚丸官方網站－聯絡資訊", "https://fishball1961.com/contact.php"]]}, {"id": 5, "file": "spot5.html", "name": "林華泰茶行", "short": "茶葉貿易與台灣茶文化", "symbol": "🍵", "year": "1883 年創立", "address": "臺北市大同區重慶北路二段 193 號", "theme": "茶文化・貿易・產業轉型", "intro": "從茶葉外銷到內銷批發，林華泰茶行的故事，能帶我們理解台灣茶產業與大稻埕商業網絡的關係。", "story": "林華泰茶行創立於 1883 年，是台北歷史悠久的茶行之一。國家文化記憶庫資料指出，林家原本從事茶產業，後來在台北設立茶廠並拓展茶葉外銷；戰後外銷市場變化，茶行逐漸轉向內銷。店內保留大型茶葉鐵桶及部分製茶、販茶工具，建築也已登錄為歷史建築，呈現店鋪、工廠與住宅空間結合的產業特色。", "memory": "喝茶可能是待客、聊天、休息或家人相聚的日常。茶行保存的不只有茶葉，也包含選茶、焙茶、包裝、交易與招呼客人的生活方式。", "question": "在你的家庭裡，喝茶是一種日常習慣、待客禮貌，還是特別的家庭回憶？", "map": "林華泰茶行 臺北市大同區重慶北路二段193號", "sources": [["國家文化記憶庫－林華泰茶行", "https://tcmb.culture.tw/zh-tw/detail?id=601589&indexCode=Culture_Place"], ["文化部文化資產局－林華泰茶行歷史建築", "https://nchdb.boch.gov.tw/assets/overview/historicalBuilding/20160822000001"]]}];

const KEY = "taipeiMemoryVisited";
const $ = (id) => document.getElementById(id);
function readVisited(){ try{return JSON.parse(localStorage.getItem(KEY)||"[]")}catch(e){return []} }
function writeVisited(ids){ localStorage.setItem(KEY,JSON.stringify(ids)); }
function mapsUrl(query){return "https://www.google.com/maps/search/?api=1&query="+encodeURIComponent(query)}
function directionsUrl(){
 const names = SPOTS.map(s=>s.map);
 const origin=encodeURIComponent(names[0]), destination=encodeURIComponent(names[names.length-1]);
 const waypoints=names.slice(1,-1).map(encodeURIComponent).join("%7C");
 return `https://www.google.com/maps/dir/?api=1&origin=${origin}&destination=${destination}&waypoints=${waypoints}&travelmode=walking`;
}
function renderCards(){
 const host=$("shopGrid"); if(!host)return;
 host.innerHTML=SPOTS.map(s=>`
  <article class="shop-card">
   <div class="shop-top" data-symbol="${s.symbol}">
    <div class="shop-number">STOP 0${s.id} / 05</div>
    <h3>${s.name}</h3>
   </div>
   <div class="shop-body">
    <div class="meta">${s.year}　・　${s.theme}</div>
    <p>${s.short}。${s.intro}</p>
    <div class="card-actions">
     <a href="${s.file}">閱讀故事 →</a>
     <a href="${mapsUrl(s.map)}" target="_blank" rel="noopener">地圖導航 ↗</a>
    </div>
   </div>
  </article>`).join("");
}
function renderStamps(){
 const host=$("stampGrid"); if(!host)return;
 const visited=readVisited();
 host.innerHTML=SPOTS.map(s=>`
  <div class="stamp ${visited.includes(s.id)?"done":""}">
   <span class="symbol">${s.symbol}</span>
   <strong>0${s.id}</strong><br>${s.name.replace("（原味香魚丸）","")}
   <div>${visited.includes(s.id)?"已收集 ✓":"尚未收集"}</div>
  </div>`).join("");
 const count=visited.length;
 if($("stampCount"))$("stampCount").textContent=`已收集 ${count} / 5 枚印章`;
 if($("progressBar"))$("progressBar").style.width=(count/5*100)+"%";
}
function renderDetail(){
 const body=document.body;
 if(body.dataset.page!=="spot")return;
 const id=Number(body.dataset.spot);
 const s=SPOTS.find(x=>x.id===id);
 if(!s)return;
 document.title=`${s.name}｜台北記憶導覽`;
 $("spotNumber").textContent=`STOP 0${s.id} / 05`;
 $("spotName").textContent=s.name;
 $("spotShort").textContent=s.short;
 $("spotYear").textContent=s.year;
 $("spotTheme").textContent=s.theme;
 $("spotAddress").textContent=s.address;
 $("spotIntro").textContent=s.intro;
 $("spotStory").textContent=s.story;
 $("spotMemory").textContent=s.memory;
 $("spotQuestion").textContent=s.question;
 $("mapLink").href=mapsUrl(s.map);
 $("sourceLinks").innerHTML=s.sources.map(([label,url])=>`<a href="${url}" target="_blank" rel="noopener">${label} ↗</a>`).join("");
 const prev=SPOTS[s.id-2], next=SPOTS[s.id];
 const nav=$("pageNav");
 nav.innerHTML=`
  <a href="${prev?prev.file:"index.html"}"><small>← 上一站</small><strong>${prev?prev.name:"返回導覽首頁"}</strong></a>
  <a href="${next?next.file:"index.html"}"><small>${next?"下一站 →":"旅程完成"}</small><strong>${next?next.name:"回到首頁收集印章"}</strong></a>`;
 const btn=$("collectButton");
 const visited=readVisited();
 btn.textContent=visited.includes(s.id)?"✓ 已收集這一站印章":"收集這一站印章";
 btn.addEventListener("click",()=>{
   const now=readVisited();
   if(!now.includes(s.id))now.push(s.id);
   writeVisited(now); btn.textContent="✓ 已收集這一站印章";
 });
 renderStamps();
}
function init(){
 renderCards(); renderStamps(); renderDetail();
 const route=$("routeLink"); if(route)route.href=directionsUrl();
 const reset=$("resetStamps");
 if(reset)reset.addEventListener("click",()=>{if(confirm("確定要清除這台裝置上的五站集章紀錄嗎？")){writeVisited([]);renderStamps();}});
}
document.addEventListener("DOMContentLoaded",init);
